          "gu": "સ્નેહા સામે પ્રશ્ન આવ્યો: 'શાળાની લાઈબ્રેરીએ ૫૦૦ કોમિક્સ ખરીદવી જોઈએ જેથી બાળકોનો વાંચન સમય વધે.' વિકલ્પ A: 'બાળકોને કોમિક્સ ગમે છે.' સ્નેહાએ તેને ઉલટાવ્યું: 'બાળકોને કોમિક્સ ગમતી નથી.' જો ગમતી જ ન હોય, તો વાંચન સમય ક્યારેય ન વધે! તારણ નષ્ટ થયું, સાબિત થયું કે વિકલ્પ A જ સાચી પૂર્વધારણા હતી!"
