          "en": "Priya used to rush through her Class 8 Math tests and daydream during the final 15 minutes. She started writing confidence percentages next to each question number. On her last test, she tagged 18 questions as 90%, 5 questions as 70%, and 2 questions as 50%. In the final 15 minutes, she ignored the 90% questions and worked exclusively on the two 50% questions, catching an algebraic sign error that saved her an A+ grade!",
